    for (size_t i = 0; i < 6; i++) CHECK(dm_savepkg_name_ok(ok[i]), "应合规 %s", ok[i]); for (size_t i = 0; i < 11; i++) CHECK(!dm_savepkg_name_ok(bad[i]), "应不合规 %s", bad[i]);
