    CHECK(dm_savepkg_keepboth_name("abcdefghijklmno", o, sizeof o, NULL, NULL) && !strcmp(o, "abcdefghijklm-A"), "%s", o); CHECK(dm_savepkg_keepboth_name("一二三四五", o, sizeof o, NULL, NULL) && dm_savepkg_name_ok(o) && strlen(o) <= 15, "%s", o);
